INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0557f416-b9b8-4728-8cb5-7aceb898d048', 'わたしは、医大を目ざしてべん強しています。', 'Saya sedang belajar untuk masuk ke sekolah kedokteran.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0557f416-b9b8-4728-8cb5-7aceb898d048', '医者のたまごをかれ氏にするため、医大生のふりをして、医大にせん入してみました。', 'Saya berpura-pura menjadi mahasiswa kedokteran dan menyelinap ke sekolah kedokteran untuk mencari calon pacar dokter.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0557f416-b9b8-4728-8cb5-7aceb898d048', '私は、ポケモンコレクションを売って、医大の学費を払った。', 'Saya membayar biaya sekolah kedokteran dengan menjual koleksi Pokémon saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d9ada6ff-a770-4304-a448-d29cb60f0198', 'vocabulary', '医大', '医大', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda pernah melihat 大学 berarti "perguruan tinggi". Jadi ambil 大 dan masukkan ke dalam obat untuk mendirikan "perguruan tinggi kedokteran", atau universitas kedokteran.', 'Anda pernah melihat 大学 berarti "perguruan tinggi". Jadi ambil 大 dan masukkan ke dalam obat untuk mendirikan "perguruan tinggi kedokteran", atau universitas kedokteran.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
