INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', 'いしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', '今日は医者に行かなくちゃいけない。', 'Saya harus pergi ke dokter hari ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', 'ある夜、とあるあやしいレストランに、もくもくとサメを食べる三人の医者がいました。', 'Suatu malam, di sebuah restoran yang teduh, ada tiga dokter yang mengisi diri mereka dengan ikan hiu.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('97c3c68f-17a3-4fa0-ac6c-5feb303d8bcc', '僕は医者になりたいけど、人に触ることが嫌いなんだ。それってやっぱり問題かな？', 'Aku ingin menjadi dokter, tapi aku benci menyentuh orang. Apakah menurut Anda itu akan menjadi masalah?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'vocabulary', '究明', '究明', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ketika Anda mencerahkan penelitian Anda, itu seperti Anda menyorotinya. Untuk melakukan itu, Anda harus melakukan penyelidikan. 
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'Investigasi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'きゅうめい', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'お前は本当にしんそうを究明するつもりがあるのか？', 'Apakah Anda benar-benar akan menyelidiki kebenarannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', 'コウイチのおかしな言どうのしんのどうきはまだ究明されていない。', 'Motif sebenarnya di balik perkataan dan perbuatan aneh Koichi belum terungkap.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e16b73a7-5455-40d3-8900-4e91b53bd151', '私が大学で取っている授業の一つで、現在「鳥が先か卵が先か」について究明しているんです。', 'Salah satu mata kuliah yang saya ambil di perguruan tinggi saat ini sedang menyelidiki apakah ayam atau telur lebih dulu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('6e01c1f1-4dca-4aee-a3b9-ccd0e2e9f479', 'vocabulary', '作者', '作者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Seseorang yang membuat adalah seseorang yang menciptakan sesuatu. Dulu, pencipta seperti ini mungkin dikenal dengan banyak hal, namun yang paling menonjol adalah seorang penulis.', 'Seseorang yang membuat adalah seseorang yang menciptakan sesuatu. Dulu, pencipta seperti ini mungkin dikenal dengan banyak hal, namun yang paling menonjol adalah seorang penulis.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
