INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e60c6961-296d-4e86-93fc-41b5c7a68f33', '大事なのは、きちんとあいさつをすることです。', 'Yang penting adalah menyapa mereka dengan baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e60c6961-296d-4e86-93fc-41b5c7a68f33', '日本ごのべんきょうのために、毎日ワニカニにログインしてレビューをするのはとても大事なことです。', 'Masuk ke WaniKani dan melakukan review setiap hari sangat penting untuk pembelajaran bahasa Jepang Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e60c6961-296d-4e86-93fc-41b5c7a68f33', 'リラックスする時間をとることは、とても大事だよ。', 'Meluangkan waktu untuk bersantai itu penting.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('704418c4-de8f-4e53-ad99-2d61b39b6b5c', 'vocabulary', '食事', '食事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Tindakan makan adalah saat Anda makan.', 'Tindakan makan adalah saat Anda makan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
