INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a7aa654c-47a3-487a-b43d-2e3e6cc880ca', 'このもんだいでは、始めにしつもんをきいてください。', 'Untuk soal ini, silakan mulai dengan mendengarkan pertanyaannya.') ON CONFLICT DO NOTHING;
