INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('b8b911f2-2656-44c9-ade9-b36c01c901f6', 'vocabulary', '物', '物', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain benda, ia mempunyai arti yang berkaitan dengan benda dan benda.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna. Selain benda, ia mempunyai arti yang berkaitan dengan benda dan benda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
