INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('810b38d7-aa06-4906-8d50-7f65c2fc747d', 'ポートランドの名物は何ですか。', 'Apa keistimewaan Portland?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('810b38d7-aa06-4906-8d50-7f65c2fc747d', 'トーフグの名物社長から、東京名物の東京ばななをおみやげにもらいました。', 'Saya mendapatkan "Pisang Tokyo" yang terkenal di Tokyo dari presiden Tofugu yang terkenal unik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('810b38d7-aa06-4906-8d50-7f65c2fc747d', 'たこ焼きは絶対に大阪名物の一つです。', 'Takoyaki jelas merupakan salah satu makanan paling terkenal di Osaka.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', 'vocabulary', '物語', '物語', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Bahasa tentang berbagai hal. Ini membingungkan. Anggap saja seperti seseorang sedang membicarakan sesuatu, apa saja, sungguh. Seseorang yang hanya membicarakan sesuatu adalah seseorang yang bercerita. Jadi, kata ini berarti dongeng atau cerita atau legenda (bukan Tom Cruise).', 'Bahasa tentang berbagai hal. Ini membingungkan. Anggap saja seperti seseorang sedang membicarakan sesuatu, apa saja, sungguh. Seseorang yang hanya membicarakan sesuatu adalah seseorang yang bercerita. Jadi, kata ini berarti dongeng atau cerita atau legenda (bukan Tom Cruise).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
