INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', '物語の主人公にでもなったつもりでいるんだろう。', 'Saya pikir dia bertindak seolah-olah dia adalah karakter utama sebuah cerita.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', '竹とり物語は日本の有名な物語です。', 'Kisah Pemotong Bambu adalah legenda Jepang yang terkenal.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('70fa2198-1222-432a-8ce7-9857957a3f33', '今物語を書いているんです。悲しい子犬フェチの男の話です。', 'Saya sedang menulis cerita sekarang. Ini tentang seorang pria sedih yang terobsesi dengan anak anjing.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'vocabulary', '注ぐ', '注ぐ', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menuangkan jadi versi vocab verbanya adalah menuangkan.', 'Kata ini terdiri dari kanji dengan hiragana ditempelkan. Karena hiragana diakhiri dengan bunyi う, Anda tahu kata ini adalah kata kerja. Kanjinya sendiri artinya menuangkan jadi versi vocab verbanya adalah menuangkan.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
