INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'そそぐ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'つぐ', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'もしかして、わたしのコーラに牛にゅう注いだ？', 'Apakah kamu kebetulan menuangkan susu ke dalam minuman bersodaku?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', 'コウイチは、今年はAKB48をおうえんすることに全力を注いでいます。', 'Koichi mencurahkan seluruh energinya untuk mendukung AKB48 tahun ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('d5bd929f-f589-4be3-930b-7e43b9d2f317', '「もう少しワインを注いでいただけますか？」「もちろん。“そこまで”って言ってくださいね。」「あ、そこまで！それくらいで結構です。有難うございます。」', '"Bisakah kamu menuangkan anggur lagi untukku?" "Tentu. Katakan saja kapan." "Ya! Itu sempurna. Terima kasih."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'vocabulary', '注文', '注文', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda menuangkan tulisan ke dalam formulir. Anda mengisi formulir ini untuk memesan sesuatu yang baru untuk Anda sendiri. Ini adalah permintaan formal untuk mendapatkan barang baru ini (bayangkan itu adalah sesuatu yang ingin Anda pesan saat ini, dan bayangkan diri Anda memesannya dengan menuangkan tulisan ke formulir pemesanan).', 'Anda menuangkan tulisan ke dalam formulir. Anda mengisi formulir ini untuk memesan sesuatu yang baru untuk Anda sendiri. Ini adalah permintaan formal untuk mendapatkan barang baru ini (bayangkan itu adalah sesuatu yang ingin Anda pesan saat ini, dan bayangkan diri Anda memesannya dengan menuangkan tulisan ke formulir pemesanan).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'Pesan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'Request', false) ON CONFLICT DO NOTHING;
