INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'スタバの注文の仕方がいまいちよく分からないんだけど。', 'Saya kurang paham cara pesan di Starbucks.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'まさか注文するのをわすれてたりしないよね。', 'Anda tidak lupa memesannya, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('5f624116-736d-4388-8f40-bd28209e0945', 'それは無理な注文だが、やるっきゃない。', 'Itu permintaan yang tidak masuk akal tapi kami tidak punya pilihan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('55b31e04-9442-416d-a657-70da80237045', 'vocabulary', '味', '味', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.', 'Kanji dan kata-katanya sama persis. Itu berarti mereka juga berbagi makna.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
