INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55b31e04-9442-416d-a657-70da80237045', '味がお口に合うといいんですが。', 'Saya harap rasanya sesuai dengan selera Anda.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55b31e04-9442-416d-a657-70da80237045', 'しょう味きげんをすぎたから、味はちょっとかわってるかもしれないけど、まだ食べられると思うよ。', 'Ini sudah lewat tanggal kadaluwarsanya, jadi mungkin rasanya tidak sama, tapi menurutku masih bisa dimakan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('55b31e04-9442-416d-a657-70da80237045', 'このフグの刺し身の味、最高だよ！まさにこれだって感じだね！', 'Sashimi ikan buntal ini rasanya luar biasa! Hanya apa yang saya inginkan!') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ab5b014-4850-416f-b0b5-36875cd82a19', 'vocabulary', '下町', '下町', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda memiliki kota di bawah ini. Apakah ini terdengar familier? Kita punya kata lain untuk itu dalam bahasa Inggris, tapi intinya sama: pusat kota. Ini bukan pusat kota yang biasa Anda kunjungi. Di Jepang, ini adalah kata lama yang digunakan untuk kawasan komersial secara harfiah, yang secara fisik berada di bawah (lebih rendah dari) kota utama. Jadi bayangkan sebuah kawasan perkotaan Jepang yang kuno!', 'Anda memiliki kota di bawah ini. Apakah ini terdengar familier? Kita punya kata lain untuk itu dalam bahasa Inggris, tapi intinya sama: pusat kota. Ini bukan pusat kota yang biasa Anda kunjungi. Di Jepang, ini adalah kata lama yang digunakan untuk kawasan komersial secara harfiah, yang secara fisik berada di bawah (lebih rendah dari) kota utama. Jadi bayangkan sebuah kawasan perkotaan Jepang yang kuno!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
