INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ab5b014-4850-416f-b0b5-36875cd82a19', 'わたしは、下町でそだちました。', 'Saya tumbuh di pusat kota.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ab5b014-4850-416f-b0b5-36875cd82a19', 'とうきょうの下町にあるむかしながらのさかばに行ってみたいです。', 'Saya ingin pergi ke salon kuno yang bagus di kawasan jalan belakang kota tua Tokyo.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ab5b014-4850-416f-b0b5-36875cd82a19', '下町とは、日本の古いスタイルのダウンタウンのことで、現代のものとは異なっている。', 'Shitamachi adalah pusat kota gaya Jepang kuno; ini tidak sama dengan pusat kota yang kita pikirkan saat ini.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', 'vocabulary', '東京', '東京', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ibukota Timur di Jepang adalah Tokyo. Jika Anda melihat di peta dan membandingkannya dengan 京都 (Kyoto, ibu kota lain dalam sejarah), Anda akan melihat bahwa itu adalah sebelah Timur Kyoto, menjadikannya Ibu Kota Timur, Tokyo.', 'Ibukota Timur di Jepang adalah Tokyo. Jika Anda melihat di peta dan membandingkannya dengan 京都 (Kyoto, ibu kota lain dalam sejarah), Anda akan melihat bahwa itu adalah sebelah Timur Kyoto, menjadikannya Ibu Kota Timur, Tokyo.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', 'Tokyo', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', 'Toukyou', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', 'とうきょう', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', '東京えきから中川えきまででんしゃで行って、中川えきからみかん山までバスで行きます。', 'Kita akan naik kereta dari stasiun Tokyo ke stasiun Nakagawa, lalu kita akan naik bus dari stasiun Nakagawa ke gunung Mikan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', '今から東京に行かなくてはいけないので、そろそろお会けいおねがいします。', 'Saya harus pergi ke Tokyo sekarang, bolehkah saya minta tagihannya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e8a655b4-f4cc-480b-816e-e2517788daa6', '東京についてすぐに、マクドナルドに行った。', 'Begitu saya tiba di Tokyo, saya pergi ke McDonald''s.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('3a161219-aaa0-45f3-84f8-d959fab0badb', 'vocabulary', '安売り', '安売り', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Saat Anda menjual sesuatu dengan harga murah, Anda menjualnya dengan harga diskon. Alternatifnya, Anda dapat mengingat kata ini sebagai jual murah atau jual murah. Ini adalah penawaran bagus!', 'Saat Anda menjual sesuatu dengan harga murah, Anda menjualnya dengan harga diskon. Alternatifnya, Anda dapat mengingat kata ini sebagai jual murah atau jual murah. Ini adalah penawaran bagus!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
