INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('85132cfa-362a-4831-9745-d50de1373232', 'Flier', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('85132cfa-362a-4831-9745-d50de1373232', 'おしらせ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85132cfa-362a-4831-9745-d50de1373232', 'あのう、お知らせしたいことがあるんですが、今、いいですか？', 'Permisi, ada sesuatu yang ingin saya sampaikan kepada Anda - apakah Anda punya waktu sekarang?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85132cfa-362a-4831-9745-d50de1373232', '学校からのお知らせはもうよみましたか？', 'Apakah kamu sudah membaca pemberitahuan dari sekolah?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('85132cfa-362a-4831-9745-d50de1373232', '残念なお知らせがあります。昨夜誰かがこの家に侵入し、冷凍庫に入っていたアイスクリームを全部盗んでしまいました。', 'Saya punya kabar buruk. Seseorang masuk ke rumah kami tadi malam dan mencuri semua es krim yang kami simpan di freezer.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'vocabulary', '目医者', '目医者', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Apakah Anda ingat 医者 (dokter)? Apa yang terjadi jika Anda memperhatikan di sana? Anda memiliki seorang dokter mata.', 'Apakah Anda ingat 医者 (dokter)? Apa yang terjadi jika Anda memperhatikan di sana? Anda memiliki seorang dokter mata.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
