INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'Oculist', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'Ophthalmologist', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'めいしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', 'きのう目がいたくなって、目医者に行ったら、ものもらいだった。', 'Mata saya mulai sakit kemarin, saya berobat ke dokter mata, dan itu bintit.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', '週末も開いている目医者をさがしています。', 'Saya mencari dokter mata yang buka pada akhir pekan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('686fdf8d-7853-4c51-9afe-64d2b87d6b25', '「よお、目医者さん。もう何もかもばれているんだよ。だから、目について何も知らないふりをする必要はないぜ。」', 'Dengar, Tuan Dokter Mata. Kucing sudah keluar dari tas, jadi tidak perlu berpura-pura tidak tahu apa-apa tentang mata.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'vocabulary', '使い方', '使い方', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda sudah melihat kata 使う semoga sekarang. Jika pernah, Anda pasti tahu artinya "menggunakan". Jadi, cara menggunakan sesuatu adalah cara menggunakan (alias cara menggunakan). Ini akan menjadi kata yang Anda lihat saat Anda melihat petunjuk cara menggunakan sesuatu.', 'Anda sudah melihat kata 使う semoga sekarang. Jika pernah, Anda pasti tahu artinya "menggunakan". Jadi, cara menggunakan sesuatu adalah cara menggunakan (alias cara menggunakan). Ini akan menjadi kata yang Anda lihat saat Anda melihat petunjuk cara menggunakan sesuatu.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'Cara Menggunakan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'Way Of Using', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'つかいかた', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'もう少し、言葉の使い方に気を付けた方がいいでしょ。', 'Anda harus lebih berhati-hati dalam menggunakan bahasa.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', 'アイフォンの使い方が分かりません。', 'Saya tidak tahu cara menggunakan iPhone.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a71fc4cf-7653-4eb4-9fe5-14032019ba08', '一緒に仕事ができるように、俺の犬に金槌の使い方を訓練してみようと思うんだ。', 'Saya akan melatih anjing saya cara menggunakan palu dan membawanya bekerja bersama saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', 'vocabulary', '仕事', '仕事', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', '"Tindakan yang Anda lakukan" adalah hal-hal yang Anda lakukan. Apa yang Anda katakan ketika seseorang bertanya "apa yang Anda lakukan"? Anda memberi tahu mereka apa pekerjaan Anda.', '"Tindakan yang Anda lakukan" adalah hal-hal yang Anda lakukan. Apa yang Anda katakan ketika seseorang bertanya "apa yang Anda lakukan"? Anda memberi tahu mereka apa pekerjaan Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', 'Pekerjaan', true) ON CONFLICT DO NOTHING;
