INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', 'Occupation', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', 'しごと', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', 'この仕事は、交通ひこみですか？', 'Apakah pekerjaan ini mengganti biaya transportasi?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', '赤ちゃんの仕事は泣くことです。', 'Urusan bayi adalah menangis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('c3b6f98f-73ce-4a48-97f3-b29bd88f566f', '「時間内に、この仕事を終えられると思うか？」「さあ、それはどうかな。」', '“Apakah menurutmu kita bisa menyelesaikan pekerjaan ini tepat waktu?” "Yah, aku tidak akan bertaruh."') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', 'vocabulary', '注文する', '注文する', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda mungkin pernah melihat kata 注文 (pesanan, permintaan). Ini hanyalah versi kata kerjanya: memesan / meminta.', 'Anda mungkin pernah melihat kata 注文 (pesanan, permintaan). Ini hanyalah versi kata kerjanya: memesan / meminta.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', 'Untuk Memesan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', 'To Request', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', 'ちゅうもんする', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', '銀色のラメの入ったラッピングペーパーを注文しました。', 'Saya memesan kertas kado yang dilapisi glitter perak.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', 'アマゾンで、間ちがえてコウイチの使用ずみブリーフを注文してしまった。', 'Saya tidak sengaja memesan celana bekas Koichi di Amazon.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('36212847-6e68-4d83-a945-2c8e19547e20', '外食でも、お持ち帰りで注文しても、僕はどちらでも構わないよ。', 'Kita bisa makan di luar atau memesan makanan untuk dibawa pulang. Saya tidak keberatan dengan satu atau lain cara.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', 'vocabulary', '〜的', '〜的', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Saya khawatir ini adalah kata yang aneh. Anda harus menanggungnya. Ini, ketika ditambahkan ke sebuah kata, seperti menambahkan "-al" ke sebuah kata (atau -seperti ke sebuah kata). Misalnya, tambahkan ke 日本 (Jepang) dan Anda akan mendapatkan "Seperti Jepang", yang hasilnya adalah "Sangat Jepang". Ini adalah jenis modifikasi kata yang aneh yang sangat bergantung pada setiap situasi yang ada, meskipun -al dan -like sering kali berfungsi dengan baik. Untuk saat ini, ketahuilah bahwa kata ini memiliki arti seperti ini. Kami akan mulai menerapkannya pada berbagai kata di masa depan, perlahan tapi pasti.', 'Saya khawatir ini adalah kata yang aneh. Anda harus menanggungnya. Ini, ketika ditambahkan ke sebuah kata, seperti menambahkan "-al" ke sebuah kata (atau -seperti ke sebuah kata). Misalnya, tambahkan ke 日本 (Jepang) dan Anda akan mendapatkan "Seperti Jepang", yang hasilnya adalah "Sangat Jepang". Ini adalah jenis modifikasi kata yang aneh yang sangat bergantung pada setiap situasi yang ada, meskipun -al dan -like sering kali berfungsi dengan baik. Untuk saat ini, ketahuilah bahwa kata ini memiliki arti seperti ini. Kami akan mulai menerapkannya pada berbagai kata di masa depan, perlahan tapi pasti.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
