INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', '自分的には上手にアメリカ的なスピーチができたと思ってたんだけどな。', 'Saya pribadi merasa mampu menyampaikan pidato gaya Amerika dengan cukup baik.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', 'コウイチの神ぴ的なえみが、こ人的にめっちゃツボなんだよね。', 'Saya pribadi menyukai senyum misterius Koichi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('42e480bd-30d9-4b4d-afd3-0584125b932f', 'トーフグ的秘密計画って一体何ですか？もう少し具体的におっしゃって頂けませんか？', 'Apa maksudmu dengan rencana rahasia seperti Tofugu? Apakah menurut Anda Anda bisa lebih spesifik?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'vocabulary', '日本的', '日本的', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Hal-hal yang menjadi sasaran orang Jepang lebih dari sekedar orang Jepang, mereka sangat Jepang. Kata ini mungkin sulit dipahami pada awalnya, namun ada banyak hal yang dianggap hanya bahasa Jepang oleh orang Jepang. Teori-teori ini berkisar dari yang masuk akal hingga yang konyol, tetapi bagaimanapun juga, Anda akan melihatnya digambarkan sebagai 日本的.', 'Hal-hal yang menjadi sasaran orang Jepang lebih dari sekedar orang Jepang, mereka sangat Jepang. Kata ini mungkin sulit dipahami pada awalnya, namun ada banyak hal yang dianggap hanya bahasa Jepang oleh orang Jepang. Teori-teori ini berkisar dari yang masuk akal hingga yang konyol, tetapi bagaimanapun juga, Anda akan melihatnya digambarkan sebagai 日本的.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'Sangat Jepang', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'Typically Japanese', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'にほんてき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', '日本的なくらしにあこがれています。', 'Saya mendambakan kehidupan ala Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'このアニメはとても日本的ですね。', 'Anime ini sangat Jepang ya?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e3f37196-7b4b-478b-80b1-b1c11b5695b3', 'フグは、サーモンの中に「日本的な優しさ」を見出した。', 'Fugu menemukan kelembutan khas Jepang pada Salmon.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', 'vocabulary', '目的', '目的', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ketika mata Anda tertuju pada target, Anda tahu tujuan Anda. Anda juga memperhatikan tujuannya (bagaimanapun juga, itulah targetnya!).', 'Ketika mata Anda tertuju pada target, Anda tahu tujuan Anda. Anda juga memperhatikan tujuannya (bagaimanapun juga, itulah targetnya!).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', 'Tujuan', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', 'Goal', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', 'Motive', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', 'もくてき', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', '一体、目的は何なんですか？', 'Apa tujuanmu?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', '着付けが出来るようになるのが目的で、この料ていで働き始めました。', 'Saya mulai bekerja di restoran mewah bergaya Jepang ini dengan motif saya bisa memakai kimono.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('26d875ac-49b6-413d-b028-e0ed408a8926', '私たちの目的は、一緒に楽しみながら皆さんに日本語を勉強してもらうことです。', 'Tujuan kami adalah membuat Anda semua bersenang-senang sambil belajar bahasa Jepang bersama.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', 'vocabulary', '英語', '英語', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Bahasa Inggris adalah bahasa yang Anda baca saat ini. Ini adalah bahasa Inggris. Itu bahasa Inggris.', 'Bahasa Inggris adalah bahasa yang Anda baca saat ini. Ini adalah bahasa Inggris. Itu bahasa Inggris.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', 'Bahasa Inggris', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', 'English', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', 'えいご', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', '英語の発音は日本語の発音よりむずかしいと思う。', 'Menurut saya, pengucapan bahasa Inggris lebih sulit daripada pengucapan bahasa Jepang.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', 'もしこのレストランの店員も英語が話せるようだったら、今後わざわざあの店まで行かなくてすむようになるね。', 'Jika pekerja restoran ini ternyata bisa berbahasa Inggris, kita tidak perlu jauh-jauh pergi ke restoran lain lagi.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('286ccfa9-1bd7-4f59-8d94-68c1a8297c70', '「僕たちは皆、英語と数学の授業が嫌いだ。」「ちょっと、一緒にしないでよ。私は両方共好きだし。」', '"Kami semua membenci kelas Bahasa Inggris dan Matematika." “Hei, bicaralah sendiri. Aku suka keduanya.”') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', 'vocabulary', '英会話', '英会話', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Pertemuan bahasa Inggris dan berbicara satu sama lain. Ini adalah Percakapan Bahasa Inggris. Ini banyak digunakan ketika berbicara tentang "berbicara dalam bahasa Inggris" untuk belajar bahasa Inggris dan yang lainnya.', 'Pertemuan bahasa Inggris dan berbicara satu sama lain. Ini adalah Percakapan Bahasa Inggris. Ini banyak digunakan ketika berbicara tentang "berbicara dalam bahasa Inggris" untuk belajar bahasa Inggris dan yang lainnya.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', 'Percakapan Bahasa Inggris', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', 'えいかいわ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', '私の兄は、英会話は上手だけど、計算は下手なんです。', 'Kakak laki-laki saya pandai percakapan bahasa Inggris, tapi buruk dalam perhitungan.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', 'まさか。また英会話のテストに落ちちゃったよ。ショックすぎる。', 'Oh tidak, saya tidak percaya saya gagal lagi dalam tes percakapan bahasa Inggris. Saya sangat terkejut.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('484f8191-a82a-4549-888a-01ff1c84edf1', '英会話の試験でミスをしたことで動揺してしまい、さらに別のミスを誘発することになってしまいました。', 'Saya tahu saya melakukan satu kesalahan pada ujian percakapan bahasa Inggris dan saya sangat bingung sehingga akhirnya memicu kesalahan lainnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'vocabulary', '英文', '英文', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Tulisan Inggris adalah Penulisan Bahasa Inggris (atau jika Anda ingin lebih suka, Komposisi Bahasa Inggris).', 'Tulisan Inggris adalah Penulisan Bahasa Inggris (atau jika Anda ingin lebih suka, Komposisi Bahasa Inggris).') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'Penulisan Bahasa Inggris', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'English Composition', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'えいぶん', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'ここに日本語で文をかいて、その下に英文でやくを付けてください。', 'Silakan tulis kalimat dalam bahasa Jepang di sini dan tambahkan terjemahan bahasa Inggris di bawahnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'わたしの母は高校の英語の先生になるために、大学で英文科をそつ業したそうです。', 'Saya mendengar bahwa ibu saya lulus dari Jurusan Komposisi Bahasa Inggris di perguruan tinggi untuk menjadi guru bahasa Inggris di sekolah menengah.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('f3b61e9b-41e6-4788-9a15-30d606d0952d', 'ねぇ、忙しいところ悪いんだけどさ、この英文の翻訳にちょっと手こずっちゃってるんだよね。手伝ってもらえないかな？', 'Hei, maaf mengganggu Anda, tapi saya agak terjebak pada terjemahan kalimat bahasa Inggris ini. Bisakah Anda membantu saya?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'vocabulary', '英国', '英国', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Negara Inggris adalah tempat Inggris berada. Kata ini bisa merujuk pada Inggris, Britania Raya, dan Inggris!
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'Inggris', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'Uk', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'United Kingdom', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'England', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'えいこく', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', 'あの頑固な英国首相をせっとくするのはとても大変だったでしょう？', 'Membujuk perdana menteri Inggris yang keras kepala itu merupakan pekerjaan yang sangat sulit, bukan?') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', '毎年、大変な数の人たちが、ゴルフをしに英国をおとずれます。', 'Sejumlah besar orang mengunjungi Inggris untuk bermain golf setiap tahun.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('a9d65703-8bd1-422d-b796-383215cc6252', '英国と米国は敵対関係にある。', 'Inggris mempunyai hubungan antagonis dengan Amerika.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', 'vocabulary', '明日', '明日', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Hari yang cerah bukanlah hari ini (karena hari ini sangat buruk), melainkan hari esok, karena Anda selalu dapat memandang hari esok sebagai hari yang lebih baik dan lebih cerah.', 'Hari yang cerah bukanlah hari ini (karena hari ini sangat buruk), melainkan hari esok, karena Anda selalu dapat memandang hari esok sebagai hari yang lebih baik dan lebih cerah.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
