INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', 'あした', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', 'あす', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', 'みょうにち', NULL, false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', '明日、びょういんへ行きましょう。', 'Ayo pergi ke rumah sakit besok.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', '明日は明日の風がふく。', 'Besok adalah hari yang lain.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('163c2b0b-f2fc-43c9-bc84-497c099611e1', '一ヶ月イタリアに行くことを知らせるために、明日学校に電話しなくてはいけません。', 'Saya perlu menelepon sekolah besok untuk memberi tahu mereka bahwa saya akan pergi ke Italia selama sebulan.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'vocabulary', '空車', '空車', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Ketika sebuah mobil memiliki langit di dalamnya (dan bukan, katakanlah, sekelompok orang), maka Anda bebas memberi tumpangan. Jika Anda melihat tanda ini menyala di taksi, jangan ragu untuk menghentikannya, itu akan membawa Anda ke suatu tempat. Ini adalah taksi terbuka.', 'Ketika sebuah mobil memiliki langit di dalamnya (dan bukan, katakanlah, sekelompok orang), maka Anda bebas memberi tumpangan. Jika Anda melihat tanda ini menyala di taksi, jangan ragu untuk menghentikannya, itu akan membawa Anda ke suatu tempat. Ini adalah taksi terbuka.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'Buka Taksi', true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_meanings (item_id, meaning, primary_meaning) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'Empty Parking Space', false) ON CONFLICT DO NOTHING;
INSERT INTO public.item_readings (item_id, reading, reading_type, primary_reading) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'くうしゃ', NULL, true) ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'タクシーのひょうじが「空車」となっているときは、おきゃくさんはだれものっていません。', 'Saat taksi menampilkan "Taksi Terbuka", tidak ada pelanggan di dalamnya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', 'この辺りのコインパーキングがいつも空車なのがふしぎでしょうがない。', 'Aku jadi penasaran kenapa tempat parkir di sekitar sini selalu kosong.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('fb2d5cc6-418e-4693-80b2-e1da345bac2f', '空車のタクシーが全然通らない。', 'Tidak ada taksi kosong yang melewati kami.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('8ce43b02-8146-4ba6-a0c1-009968e03dbe', 'vocabulary', '不味い', '不味い', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Anda sudah melihat 美味しい pada saat ini. Ini adalah kebalikan dari itu. Daripada 美 kamu punya 不 (tidak), jadi sesuatu yang tidak memiliki rasa adalah sesuatu yang rasanya tidak enak. yaitu sesuatu yang rasanya tidak enak. Ini juga bisa merujuk pada seseorang yang tidak terampil dalam suatu hal.', 'Anda sudah melihat 美味しい pada saat ini. Ini adalah kebalikan dari itu. Daripada 美 kamu punya 不 (tidak), jadi sesuatu yang tidak memiliki rasa adalah sesuatu yang rasanya tidak enak. yaitu sesuatu yang rasanya tidak enak. Ini juga bisa merujuk pada seseorang yang tidak terampil dalam suatu hal.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
