INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ce43b02-8146-4ba6-a0c1-009968e03dbe', 'なんか不味そうなサンドイッチだね。', 'Sandwichnya terlihat kurang menggugah selera, bukan?') ON CONFLICT DO NOTHING;
