INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('8ce43b02-8146-4ba6-a0c1-009968e03dbe', 'こんなに不味い味噌汁を飲んだことはありません。', 'Saya belum pernah makan sup miso yang menjijikkan seperti itu.') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('21ec6116-2174-4ce1-839c-31c88dcbea67', 'vocabulary', '一歩', '一歩', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Jika 歩 adalah "berjalan" dan Anda berjalan satu kali, maka sebenarnya Anda hanya mengambil satu langkah. Jika ada angka sebelum 歩, ini mengacu pada jumlah langkah yang Anda ambil. Yang paling umum adalah yang ini, dan Anda akan melihatnya di urinal ketika mereka dengan ramah meminta Anda untuk mengambil satu langkah maju karena kencing bukanlah permainan dan seseorang harus membersihkannya setelah Anda.', 'Jika 歩 adalah "berjalan" dan Anda berjalan satu kali, maka sebenarnya Anda hanya mengambil satu langkah. Jika ada angka sebelum 歩, ini mengacu pada jumlah langkah yang Anda ambil. Yang paling umum adalah yang ini, dan Anda akan melihatnya di urinal ketika mereka dengan ramah meminta Anda untuk mengambil satu langkah maju karena kencing bukanlah permainan dan seseorang harus membersihkannya setelah Anda.') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
