INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('6c88ceda-18b5-4497-b23c-0824e2e79753', 'トーフグだけは、味方してくれると思ってたんだけどな。', 'Saya pikir setidaknya Tofugu akan mendukung saya.') ON CONFLICT DO NOTHING;
