INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e614c7e5-3dc2-421a-b33d-633ea9a749d7', 'トーフグの読者が、飛行機代を出してくれたんです。', 'Pembaca Tofugu membayar tiket pesawat saya.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e614c7e5-3dc2-421a-b33d-633ea9a749d7', 'トーフグには世界中にたくさんの読者がいます。', 'Tofugu memiliki banyak pembaca di seluruh dunia.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('e614c7e5-3dc2-421a-b33d-633ea9a749d7', 'トーフグの読者のうち、日本語学習者はどのくらいいますか？', 'Di antara pembaca Tofugu, berapa banyak pembelajar bahasa Jepang?') ON CONFLICT DO NOTHING;
INSERT INTO public.items (id, type, character, slug, level, rank_id, meaning_mnemonic, description) VALUES ('277dcca1-3328-48e2-97e4-52a4eda01338', 'vocabulary', '食べ物', '食べ物', 2, 'f6a7b8c9-0d1e-2f3a-4b5c-6d7e8f9a0b1c', 'Sesuatu yang dimakan (alias "sesuatu yang Anda makan") adalah makanan. Makanlah itu. Makanlah makanan itu. Karena itu adalah "sesuatu", Anda tahu itu adalah kata benda. Menarik bagaimana kanji ini bisa mengubah kata kerja seperti ini menjadi kata benda bukan? Hati-hati karena pola ini akan muncul pada kata kerja lain juga!', 'Sesuatu yang dimakan (alias "sesuatu yang Anda makan") adalah makanan. Makanlah itu. Makanlah makanan itu. Karena itu adalah "sesuatu", Anda tahu itu adalah kata benda. Menarik bagaimana kanji ini bisa mengubah kata kerja seperti ini menjadi kata benda bukan? Hati-hati karena pola ini akan muncul pada kata kerja lain juga!') ON CONFLICT (id) DO UPDATE SET type = EXCLUDED.type, character = EXCLUDED.character, slug = EXCLUDED.slug, level = EXCLUDED.level, rank_id = EXCLUDED.rank_id, meaning_mnemonic = EXCLUDED.meaning_mnemonic, description = EXCLUDED.description;
