INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('4a33754a-f4f2-4041-849c-75a99ef2fbbe', '今年は赤いマニキュアがはやっています。', 'Tahun ini cat kuku merah sedang populer.') ON CONFLICT DO NOTHING;
