INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0975ad45-c90b-4954-8923-4420b7ee91e8', 'このゲーム、ぜったい売れるだろ。', 'Game ini pasti akan laris manis.') ON CONFLICT DO NOTHING;
INSERT INTO public.item_context_sentences (item_id, japanese, indonesian) VALUES ('0975ad45-c90b-4954-8923-4420b7ee91e8', 'その千円札、五百円でネットオークションにかけたら、よゆうで売れるっしょ。', 'Menurutku, jika kamu memasang uang seribu yen untuk lelang online, uang itu akan terjual dengan mudah seharga lima ratus yen.') ON CONFLICT DO NOTHING;
